# -*- coding: utf-8 -*-
from pathlib import Path
import shutil,re,json
r=Path.cwd();out=r/'outputs/runtime-checkpoint-50';dest=r/'publish/echoing-green/verification/fox-and-petals';dest.mkdir(parents=True,exist_ok=True)
for n in ['fox-meeting-final.png','petal-overview.png','pond-petals.png']:shutil.copy2(out/n,dest/n)
page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Koyoi · 狐狸与纸风</title><style>body{margin:0;background:#28232e;color:#eee0ce;font:16px/1.8 system-ui,sans-serif}main{max-width:1100px;margin:auto;padding:32px 20px 70px}h1{font:38px Georgia,serif}h2{font-size:23px;color:#e4bd8a}a{color:#edbe82}img{display:block;width:100%;border-radius:12px}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:12px;border-bottom:1px solid #635449}small{color:#d6c9b6}.note{padding:16px;border-left:3px solid #d8ae76;background:#322d37}@media(max-width:650px){main{padding:20px 12px}h1{font-size:30px}td,th{padding:8px;font-size:14px}}</style><main><a href="../../">← Koyoi · 今宵</a><h1>狐狸与纸风</h1><p>先跑向街坊，再用动作回应。名字统一为 Koyoi／今宵。</p><h2>跑过去，才开始亲近</h2><p>狐狸先走出明显距离，再在街坊身边站稳。双前爪抬起、身体轻轻靠近、尾巴分段摆动；对方短暂停下来回应。目标走远时会重新接近，避免对着空气做动作。</p><img src="fox-meeting-final.png" alt="实际网页：狐狸靠近街坊，抬起前爪摇尾互动"><p><small>较近的检查视角，用于看腿部和互动。图片来自真正的网页模型，没有绘图补画。</small></p><h2>修长的纸雕腿</h2><p>替换原来的短直腿：更修长的腿、细小膝关节、深色脚掌，与较轻的折纸躯干配合。行走依然按实际路程交替迈步，支撑脚贴地；停稳后才切入亲近动作。</p><h2>让一阵纸风提示主角</h2><p>移除灰白圈。几片樱色折纸花瓣低低掠过参与者周围，配合少量暖光；提示跟随本次真正参与的人或狐狸，结束后淡出。没有头顶文字，也不让全镇每个人都围满提示。</p><img src="petal-overview.png" alt="实际网页全景：纸花瓣跟随正在行动的小狐狸"><p><img loading="lazy" src="pond-petals.png" alt="实际网页：桥边喂鱼人物附近的纸花瓣提示"></p><h2>这次检查了什么</h2><table><tr><th>项目</th><th>验证</th></tr><tr><td>狐狸远处招呼</td><td>10 种已有状态逐步模拟，包括开场、运行一阵、晚市／听琴中和结束后、纸笺后、边缘朝向；均完成招呼并结束本次输入。</td></tr><tr><td>真正的腿部动作</td><td>检查最终四个关节，30／60／120 Hz 衰减后仍迈步；新膝关节弯曲，实际脚掌网格支撑地面。</td></tr><tr><td>输入与恢复</td><td>保留一次一个心愿、尽快出现动作、有进展就继续；检查中途保存恢复。没有恢复固定 15 秒上限。</td></tr><tr><td>实际网页</td><td>查看小跑、接近、前爪亲近与结束；查看全景花瓣和桥边人物提示；检查中英文名字。</td></tr></table><p class="note">这些是本轮实际检查范围，不代表重新验收过历史全部语言样本，或所有可能状态、设备与姿态。提示保留真实遮挡，花瓣没有穿透屋顶、栏杆显示。</p><p>场景、完整屋顶、固定视角、背景音乐与原模型资产保持；狐狸细化是新增的实时三维几何。API 继续沿用原安全接口，域名尚未切换。</p><p><a href="../../">去小镇输入“狐狸招呼街坊” →</a></p><p><small>CP49 <a href="../focus-markers/">灰白圈对比</a>、CP48 <a href="../fox-footsteps/">步态与点灯</a>和更早记录保留为历史。</small></p></main></html>'''
(dest/'index.html').write_text(page)
for rel,url in [('verification/index.html','fox-and-petals/'),('verification/expressive-life/index.html','../fox-and-petals/'),('verification/fox-footsteps/index.html','../fox-and-petals/'),('verification/focus-markers/index.html','../fox-and-petals/')]:
 p=r/'publish/echoing-green'/rel;s=p.read_text();banner=f'<aside style="padding:16px;margin:16px 0;background:#40323e;color:#f1e1ca;border-left:3px solid #e0b57d"><b>当前 CP50 · Koyoi：</b>狐狸先跑向街坊，腿部细化；灰白圈已换成低空纸花瓣。<a style="color:#f4c98f" href="{url}">查看本轮实际画面 →</a> 以下为历史记录。</aside>'
 if '当前 CP50 · Koyoi' not in s:s=re.sub(r'(<main[^>]*>)',lambda m:m[0]+banner,s,count=1)
 p.write_text(s)
print(json.dumps({'report':str(dest.relative_to(r)),'images':3}))
